<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api} from '../lib'
import Icon from '../components/Icon.vue'
import '../explore.css'
const now=new Date(),month=ref(`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`),items=ref([]),warnings=ref([]),busy=ref(false),error=ref(''),selected=ref('')
let alive=true,ticket=0
const days=computed(()=>{const[y,m]=month.value.split('-').map(Number),start=new Date(y,m-1,1),pad=(start.getDay()+6)%7,count=new Date(y,m,0).getDate();return Array.from({length:Math.ceil((pad+count)/7)*7},(_,i)=>{const n=i-pad+1,date=n>0&&n<=count?`${month.value}-${String(n).padStart(2,'0')}`:'';return{day:date?n:'',date,items:items.value.filter(v=>v.date===date)}})})
const currentItems=computed(()=>selected.value?items.value.filter(v=>v.date===selected.value):items.value)
async function load(){const run=++ticket;busy.value=true;error.value='';try{const data=await api('/media-calendar?month='+month.value);if(alive&&run===ticket){items.value=data.items||[];warnings.value=data.warnings||[]}}catch(e){if(alive&&run===ticket)error.value=e.message}finally{if(alive&&run===ticket)busy.value=false}}
function change(delta){const[y,m]=month.value.split('-').map(Number),date=new Date(y,m-1+delta,1);month.value=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;selected.value='';items.value=[];load()}
function today(){month.value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;selected.value='';load()}
onMounted(load);onUnmounted(()=>{alive=false;ticket++})
</script>
<template>
 <nav class="content-tabs" aria-label="追剧日历栏目"><RouterLink to="/calendar" class="active"><Icon name="CalendarCheck2"/>追剧日历</RouterLink></nav>
 <section class="media-calendar" aria-label="订阅播出日历"><header><div><button class="icon-btn" aria-label="上个月" @click="change(-1)"><Icon name="ChevronLeft"/></button><strong>{{month.replace('-','年')}}月</strong><button class="icon-btn" aria-label="下个月" @click="change(1)"><Icon name="ChevronRight"/></button></div><div><button class="btn" @click="today">本月</button><button class="icon-btn" aria-label="刷新日历" :disabled="busy" @click="load"><Icon name="RefreshCw" :class="{spin:busy}"/></button></div></header>
 <p class="calendar-caption">已订阅剧集的播出安排 · 日期以TMDB公布为准</p><p v-if="error" class="error-message" role="alert">{{error}}</p><p v-if="busy" class="explore-status" role="status">正在读取播出日期…</p>
 <div class="calendar-week"><span v-for="n in ['一','二','三','四','五','六','日']" :key="n">周{{n}}</span></div>
 <div class="calendar-grid"><button v-for="(day,i) in days" :key="i" :disabled="!day.date" class="calendar-day" :class="{selected:selected===day.date,today:day.date===`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}" :aria-label="day.date?`${day.date} ${day.items.length}集`:undefined" :aria-pressed="!!day.date&&selected===day.date" @click="selected=selected===day.date?'':day.date"><b>{{day.day}}</b><span v-for="entry in day.items.slice(0,3)" :key="entry.id" :data-tooltip="`${entry.title} S${entry.season}E${entry.episode}`">{{entry.title}} <small>E{{entry.episode}}</small></span><small v-if="day.items.length>3">另{{day.items.length-3}}集</small></button></div>
 <p v-for="message in warnings" :key="message" class="muted calendar-caption">{{message}}</p>
 </section>
 <section class="calendar-agenda"><h2>{{selected||'本月'}}播出</h2><div class="calendar-entries"><RouterLink v-for="entry in currentItems" :key="entry.id" :to="`/discover/tv/${entry.tmdb}`"><img v-if="entry.poster" :src="entry.poster" alt="" loading="lazy"/><Icon v-else name="Tv"/><div><strong>{{entry.title}}</strong><span>S{{String(entry.season).padStart(2,'0')}}E{{String(entry.episode).padStart(2,'0')}}</span><small>{{entry.date}}</small></div></RouterLink></div><p v-if="!busy&&!currentItems.length" class="explore-status">{{selected?'当天没有已公布的订阅剧集':'本月暂无已公布的订阅播出安排'}}</p></section>
</template>
<style scoped>
.media-calendar,.calendar-agenda{border:1px solid var(--border);border-radius:8px;background:var(--surface);overflow:hidden;margin-bottom:18px}.media-calendar>header{display:flex;align-items:center;justify-content:space-between;padding:14px;gap:10px}.media-calendar>header>div{display:flex;align-items:center;gap:8px}.media-calendar strong{font-size:16px;white-space:nowrap}.calendar-caption{padding:0 16px;font-size:12px;color:var(--muted)}.media-calendar>.error-message{margin:12px}.calendar-week,.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.calendar-week>span{text-align:center;font-size:12px;padding:12px;background:var(--layer-frame);color:var(--muted)}.calendar-day{display:flex;flex-direction:column;gap:5px;min-width:0;min-height:110px;padding:9px;border:0;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--surface);text-align:left;cursor:pointer;color:var(--text)}.calendar-day>b{font-size:13px}.calendar-day>span{font-size:11px;padding:4px;border-radius:4px;background:var(--primary-soft);color:var(--primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%}.calendar-day>span>small{font-size:inherit}.calendar-day>small{font-size:11px;color:var(--muted)}.calendar-day.selected{box-shadow:inset 0 0 0 1px var(--primary);background:var(--layer-frame)}.calendar-day.today>b{color:var(--primary);text-decoration:underline;text-underline-offset:4px}.calendar-day:disabled{background:var(--bg);cursor:default}.calendar-agenda{padding:18px}.calendar-agenda h2{font-size:16px;margin:0 0 16px}.calendar-entries{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}.calendar-entries>a{display:flex;gap:12px;padding:12px;border:1px solid var(--border);border-radius:8px;min-width:0}.calendar-entries img{width:48px;height:72px;object-fit:cover;border-radius:5px}.calendar-entries a>div{display:grid;gap:6px;min-width:0}.calendar-entries strong{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.calendar-entries span,.calendar-entries small{font-size:12px;color:var(--muted)}
@media(max-width:600px){.calendar-day{min-height:80px;padding:5px 3px;gap:4px}.calendar-day>span{font-size:10px;padding:3px 1px}.calendar-day>span>small{display:none}.calendar-week>span{padding:10px 2px}.media-calendar>header{padding:10px;gap:4px}.media-calendar>header>div{gap:3px}}
</style>
